import {create3DScene,createActorFactory,bind3DInput,staticCollider,dynamicBox,create3DEffects,createSynthAudio} from '../../js/3d/index.js';
import {StarterGame} from './starter-core.js';
const $=s=>document.querySelector(s);let runtime=null,factory=null,actors=[],guide=null,input=null,effects=null,sound=null,game=null,paused=false,camera=false,started=false,crates=[],bolts=new Map(),targets=[],gates=[],serial=0;
function cleanup(){serial++;input?.dispose();factory?.dispose();effects?.dispose();sound?.dispose();runtime?.dispose();runtime=factory=effects=sound=input=null;actors=[];crates=[];bolts.clear();targets=[];gates=[];}
async function start(){cleanup();started=true;const token=serial;$('#intro').hidden=true;$('#status').textContent='Loading locally bundled engine, model and physics…';try{const r=await create3DScene($('#canvas'),{quality:$('#quality').value,camera:{radius:23,minRadius:10,maxRadius:37,target:[0,0,0]},lighting:{ambient:.9,sun:1.2}});if(token!==serial){r.dispose();return;}runtime=r;const {B,scene}=r;scene.clearColor=new B.Color4(.46,.64,.76,1);const material=(name,color)=>{const m=new B.StandardMaterial(name,scene);m.diffuseColor=B.Color3.FromHexString(color);return m;},floor=B.MeshBuilder.CreateBox('starter-floor',{width:22,height:.4,depth:14},scene);floor.position.y=-.2;floor.metadata={softwareLayer:-20};floor.material=material('starter-floor','#538f97');floor.receiveShadows=true;staticCollider(r,floor);game=new StarterGame({players:+$('#players').value});for(const o of game.obstacles){const wall=B.MeshBuilder.CreateBox('starter-wall',{width:o.w,height:1.7,depth:o.d},scene);wall.position.set(o.x,.85,o.z);wall.material=material('stone','#4d697e');staticCollider(r,wall);r.shadows?.addShadowCaster(wall);}const af=await createActorFactory(r,{url:'dev/3d-starter/assets/character.glb',clips:{idle:'Idle',walk:'Walk'},palette:{team:['#6dd8dc','#ee9fd4','#e9d29c'],plume:['#f9dc7c','#d5edff','#a0d4b2']},collider:{height:1.8,radius:.35}});if(token!==serial){af.dispose();r.dispose();return;}factory=af;actors=game.players.map((p,i)=>factory.create({variant:i}));guide=factory.create({variant:2,scale:.8});for(let i=0;i<game.count;i++){const t=game.targets[i],target=B.MeshBuilder.CreatePolyhedron('beacon'+i,{type:1,size:.45},scene);target.position.set(t.x,1.1,t.z);target.material=material('beacon'+i,i?'#f4b9df':'#d9f9ee');targets.push(target);const gate=B.MeshBuilder.CreateTorus('gate'+i,{diameter:1.6,thickness:.15,tessellation:24},scene);gate.position.set(t.x,.8,-4.9);gate.rotation.x=Math.PI/2;gate.material=material('gate'+i,'#f2d97f');gates.push(gate);}sound=createSynthAudio({getSettings:()=>({volume:.1})});sound.resume();effects=create3DEffects(r);input=bind3DInput($('#canvas'),r,{ownerAt:p=>game.count===2&&p.x>=0?1:0,cameraMode:()=>camera,down:(p,e,owner)=>{if(!paused)game.move(owner,p);return{owner};},move:(p,h)=>{if(!paused&&h)game.move(h.owner,p);}});r.setUpdate(dt=>{if(!paused)game.update(dt);for(const [i,p]of game.players.entries())actors[i].update({...p.controller,scale:1},dt);guide.update({...game.guide,scale:.8},dt);for(const [i,t]of game.targets.entries()){targets[i].setEnabled(t.hp>0);targets[i].rotation.y=game.clock;gates[i].scaling.setAll(t.hp<=0?1:.7);}const ids=new Set();for(const p of game.projectiles.active){ids.add(p.id);let mesh=bolts.get(p.id);if(!mesh){mesh=B.MeshBuilder.CreatePolyhedron('pulse'+p.id,{type:1,size:.12},scene);mesh.material=material('pulse'+p.id,'#fcdf80');bolts.set(p.id,mesh);}mesh.position.set(p.x,p.y,p.z);}for(const[id,m]of bolts)if(!ids.has(id)){m.material.dispose();m.dispose();bolts.delete(id);}while(game.events.length){effects.event(game.events.shift());sound.play({frequency:700,duration:.1});}effects.update(dt);$('#status').textContent=game.done?'DELIVERY COMPLETE · both couriers reached their gates!':game.players.map(p=>`P${p.id+1}: ${p.hits}/3 beacon hits${p.finished?' · DELIVERED':''}`).join('   |   ')+(r.software?' · SOFTWARE 3D':' · WEBGL 3D');const s=r.stats();$('#stats').textContent=`${s.fps} FPS · ${s.bodies} physics bodies · ${s.meshes} active meshes · ${s.p95Ms.toFixed(1)} ms p95 · ${crates.length} reusable crates · ${game.players.map(p=>'P'+(p.id+1)+' ('+p.controller.x.toFixed(1)+', '+p.controller.z.toFixed(1)+')').join(' / ')}`;});$('#fire2').hidden=game.count<2;paused=false;r.pause(false);drop();}catch(e){$('#status').textContent='Could not start: '+e.message;$('#intro').hidden=false;}}
function drop(){if(!runtime||paused)return;const{B,scene}=runtime;for(const c of crates){c.aggregate.dispose();c.mesh.material.dispose();c.mesh.dispose();}crates=[];for(let i=0;i<4;i++){const mesh=B.MeshBuilder.CreateBox('physics-crate',{size:.6},scene);mesh.position.set(-1.2+i*.8,3+i*.7,-2.5);const m=new B.StandardMaterial('crate',scene);m.diffuseColor=B.Color3.FromHexString('#e9bd75');mesh.material=m;const aggregate=dynamicBox(runtime,mesh,{mass:1,restitution:.25});crates.push({mesh,aggregate});}}
$('#start').onclick=start;$('#restart').onclick=()=>{if(started)start();};$('#players').onchange=()=>{if(started)start();};$('#quality').onchange=()=>runtime?.setQuality($('#quality').value);$('#pause').onclick=()=>{paused=!paused;runtime?.pause(paused);sound?.pause(paused);input?.cancel();$('#pause').textContent=paused?'▶ Resume':'Ⅱ Pause';};$('#camera').onclick=()=>{camera=!camera;input?.cancel();$('#camera').textContent=camera?'Camera · drag to orbit':'Tap to move';};$('#zoomIn').onclick=()=>runtime?.cameraRig.zoom(-2);$('#zoomOut').onclick=()=>runtime?.cameraRig.zoom(2);$('#fire1').onclick=()=>{if(!paused&&game?.fire(0))sound.play({frequency:500,slide:250});};$('#fire2').onclick=()=>{if(!paused&&game?.fire(1))sound.play({frequency:600,slide:200});};$('#drop').onclick=drop;document.addEventListener('visibilitychange',()=>{if(document.hidden){paused=true;runtime?.pause(true);sound?.pause(true);$('#pause').textContent='▶ Resume';}});window.addEventListener('pagehide',cleanup);
